package sidecar
import("crypto/sha256";"encoding/hex";"encoding/json";"fmt";"strconv")
type endpoint struct{Profile,Kind string;Version int;SHA string;Bytes int};type observationRow struct{InvariantRef string `json:"invariant_ref"`;Comparator string `json:"comparator"`;SourceHex string `json:"source_value_hex"`;TargetHex string `json:"target_value_hex"`;Tolerance *int `json:"tolerance"`};type observationBundle struct{Schema string `json:"schema"`;SourceSHA string `json:"source_native_sha256"`;TargetSHA string `json:"target_native_sha256"`;Observations []observationRow `json:"observations"`}
func detectEndpoint(raw []byte)(endpoint,error){h:=sha256.Sum256(raw);ep:=endpoint{SHA:hex.EncodeToString(h[:]),Bytes:len(raw)};if len(raw)>=2&&raw[0]=='P'&&raw[1]=='K'{_,e:=InspectMLF(raw);if e!=nil{return endpoint{},e};ep.Profile="mlf-1.0";ep.Kind="mlf.package";ep.Version=1;return ep,nil};if len(raw)>=5{switch string(raw[:4]){case "ISN7":if raw[4]!=7{return endpoint{},fmt.Errorf("PROFILE_NATIVE_VERSION_UNSUPPORTED")};ep.Profile="isql-mem";ep.Kind="mem.isn7";ep.Version=7;return ep,nil;case "ISD8":if raw[4]!=8{return endpoint{},fmt.Errorf("PROFILE_NATIVE_VERSION_UNSUPPORTED")};ep.Profile="isql-mem";ep.Kind="mem.isd8";ep.Version=8;return ep,nil;case "ILI1":if raw[4]!=1{return endpoint{},fmt.Errorf("PROFILE_NATIVE_VERSION_UNSUPPORTED")};ep.Profile="isql-mem";ep.Kind="mem.ili1";ep.Version=1;return ep,nil}};if len(raw)>=4&&raw[0]==0xd5&&raw[1]==0x51{ep.Profile="isql-dsr";ep.Version=int(raw[3]);switch raw[2]{case 0xb1:ep.Kind="dsr.registry";if raw[3]!=4{return endpoint{},fmt.Errorf("PROFILE_NATIVE_VERSION_UNSUPPORTED")};case 0xc1:ep.Kind="dsr.state";if raw[3]!=5{return endpoint{},fmt.Errorf("PROFILE_NATIVE_VERSION_UNSUPPORTED")};case 0xe1:if raw[3]==5{ep.Kind="dsr.event-stream"}else if raw[3]==6{ep.Kind="dsr.causal-program"}else{return endpoint{},fmt.Errorf("PROFILE_NATIVE_VERSION_UNSUPPORTED")};case 0xb7:ep.Kind="dsr.branch";if raw[3]!=6{return endpoint{},fmt.Errorf("PROFILE_NATIVE_VERSION_UNSUPPORTED")};case 0xe2:ep.Kind="dsr.vm-program";if raw[3]<7||raw[3]>10{return endpoint{},fmt.Errorf("PROFILE_NATIVE_VERSION_UNSUPPORTED")};default:return endpoint{},fmt.Errorf("PROFILE_NATIVE_UNRECOGNIZED")};return ep,nil};return endpoint{},fmt.Errorf("PROFILE_NATIVE_UNRECOGNIZED")}
func VerifyBridge(source,target []byte,plan BridgePlan,obsJSON []byte)(BridgeReceipt,error){s,e:=detectEndpoint(source);if e!=nil{return BridgeReceipt{},e};t,e:=detectEndpoint(target);if e!=nil{return BridgeReceipt{},e};if s.Profile!=plan.SourceProfile{return BridgeReceipt{},fmt.Errorf("P4_BRIDGE_SOURCE_PROFILE_MISMATCH")};if t.Profile!=plan.TargetProfile{return BridgeReceipt{},fmt.Errorf("P4_BRIDGE_TARGET_PROFILE_MISMATCH")};if plan.SourceArtifactKind!=nil&&s.Kind!=*plan.SourceArtifactKind{return BridgeReceipt{},fmt.Errorf("P4_BRIDGE_SOURCE_ARTIFACT_MISMATCH")};if plan.TargetArtifactKind!=nil&&t.Kind!=*plan.TargetArtifactKind{return BridgeReceipt{},fmt.Errorf("P4_BRIDGE_TARGET_ARTIFACT_MISMATCH")};var b observationBundle;if e:=json.Unmarshal(obsJSON,&b);e!=nil{return BridgeReceipt{},e};if b.Schema!="isql-origin-bridge-observations/v0.5"{return BridgeReceipt{},fmt.Errorf("P4_OBSERVATION_SCHEMA_INVALID")};if b.SourceSHA!=s.SHA{return BridgeReceipt{},fmt.Errorf("P4_OBSERVATION_SOURCE_DIGEST_MISMATCH")};if b.TargetSHA!=t.SHA{return BridgeReceipt{},fmt.Errorf("P4_OBSERVATION_TARGET_DIGEST_MISMATCH")};if len(b.Observations)!=len(plan.Preserved){return BridgeReceipt{},fmt.Errorf("P4_OBSERVATION_PRESERVED_MISSING")};results:=make([]BridgeInvariantResult,0,len(plan.Preserved));allPass:=true;for i,want:=range plan.Preserved{row:=b.Observations[i];if row.InvariantRef!=want{return BridgeReceipt{},fmt.Errorf("P4_OBSERVATION_UNDECLARED")};src,e:=hex.DecodeString(row.SourceHex);if e!=nil{return BridgeReceipt{},fmt.Errorf("P4_OBSERVATION_VALUE_INVALID")};dst,e:=hex.DecodeString(row.TargetHex);if e!=nil{return BridgeReceipt{},fmt.Errorf("P4_OBSERVATION_VALUE_INVALID")};sh:=sha256.Sum256(src);dh:=sha256.Sum256(dst);res:=BridgeInvariantResult{InvariantRef:row.InvariantRef,Comparator:row.Comparator,SourceObservableSHA256:hex.EncodeToString(sh[:]),TargetObservableSHA256:hex.EncodeToString(dh[:]),SourceObservableBytes:len(src),TargetObservableBytes:len(dst),Tolerance:row.Tolerance};switch row.Comparator{case "bytes-eq":if row.Tolerance!=nil{return BridgeReceipt{},fmt.Errorf("P4_OBSERVATION_TOLERANCE_NOT_ALLOWED")};res.Passed=string(src)==string(dst);case "utf8-int-distance":if row.Tolerance==nil{return BridgeReceipt{},fmt.Errorf("P4_OBSERVATION_TOLERANCE_REQUIRED")};a,e:=strconv.Atoi(string(src));if e!=nil{return BridgeReceipt{},fmt.Errorf("P4_OBSERVATION_INTEGER_INVALID")};bb,e:=strconv.Atoi(string(dst));if e!=nil{return BridgeReceipt{},fmt.Errorf("P4_OBSERVATION_INTEGER_INVALID")};d:=a-bb;if d<0{d=-d};res.Distance=&d;res.Passed=d<=*row.Tolerance;default:return BridgeReceipt{},fmt.Errorf("P4_OBSERVATION_COMPARATOR_UNKNOWN")};if !res.Passed{allPass=false};results=append(results,res)};status:="VERIFIED";errs:=[]string{};if !allPass{status="REJECTED";for _,r:=range results{if !r.Passed{errs=append(errs,"P4_PRESERVED_INVARIANT_FAILED:"+r.InvariantRef)}}};return BridgeReceipt{Schema:"isql-origin-bridge-receipt/v0.5",Canonical:false,Status:status,Execute:false,ConversionPerformed:false,Source:NativeEndpoint{Profile:s.Profile,ArtifactKind:s.Kind,NativeVersion:s.Version,NativeSHA256:s.SHA,NativeBytes:s.Bytes},Target:NativeEndpoint{Profile:t.Profile,ArtifactKind:t.Kind,NativeVersion:t.Version,NativeSHA256:t.SHA,NativeBytes:t.Bytes},TransitionRef:plan.TransitionRef,FidelityClass:plan.FidelityClass,Preserved:plan.Preserved,Lost:plan.Lost,ValidationResults:results,ValidatorRef:plan.ValidatorRef,AuthorityRef:plan.AuthorityRef,ProvenanceRef:plan.ProvenanceRef,TemporalRef:plan.TemporalRef,OutputDigest:t.SHA,Errors:errs},nil}
type BridgeCandidate struct{Status string;Source,Target NativeEndpoint;Execute,ConversionPerformed bool};func BuildBridgeCandidate(source,target []byte,plan BridgePlan)(BridgeCandidate,error){s,e:=detectEndpoint(source);if e!=nil{return BridgeCandidate{},e};t,e:=detectEndpoint(target);if e!=nil{return BridgeCandidate{},e};if s.Profile!=plan.SourceProfile{return BridgeCandidate{},fmt.Errorf("P4_BRIDGE_SOURCE_PROFILE_MISMATCH")};if t.Profile!=plan.TargetProfile{return BridgeCandidate{},fmt.Errorf("P4_BRIDGE_TARGET_PROFILE_MISMATCH")};if plan.SourceArtifactKind!=nil&&s.Kind!=*plan.SourceArtifactKind{return BridgeCandidate{},fmt.Errorf("P4_BRIDGE_SOURCE_ARTIFACT_MISMATCH")};if plan.TargetArtifactKind!=nil&&t.Kind!=*plan.TargetArtifactKind{return BridgeCandidate{},fmt.Errorf("P4_BRIDGE_TARGET_ARTIFACT_MISMATCH")};return BridgeCandidate{Status:"CANDIDATE",Execute:false,ConversionPerformed:false,Source:NativeEndpoint{Profile:s.Profile,ArtifactKind:s.Kind,NativeVersion:s.Version,NativeSHA256:s.SHA,NativeBytes:s.Bytes},Target:NativeEndpoint{Profile:t.Profile,ArtifactKind:t.Kind,NativeVersion:t.Version,NativeSHA256:t.SHA,NativeBytes:t.Bytes}},nil}
